    for c in range(m):
        col=[g[r][c] for r in range(n)]; cnt={}
        for v in col:
            if v: cnt[v]=cnt.get(v,0)+1
        tot=sum(cnt.values()); top=max(cnt.values()); others=tot-top
        if others>0 and others<tot*0.6: Vc.append(top)
    return Hr,Vc
