            if v!=bg and g[r].count(v)>m//2:
                Hr.append(r); Hc.append(v); break
    VP=[];CP=[]
    for c in range(m):
        col=[g[r][c] for r in range(n) if r not in Hr]
        cnt2={}
        for x in col: cnt2[x]=cnt2.get(x,0)+1
        top=max(cnt2.values())
        cand=[v for v in cnt2 if cnt2[v]==top and v!=bg]
        if cand and top>=len(col): VP.append(c); CP.append(cand[0])
    h=len(Hr); v=len(VP)
    o=[[0]*(2*v+1) for _ in range(2*h+1)]
    for b in range(v):
        for i in range(2*h+1): o[i][2*b+1]=CP[b]
